// 한국외국어대학교 글로벌캠퍼스 (경기 용인시 처인구 모현읍 외대로 81). Data is generated by scripts/campuses/hufsglobal/build-package.mjs
// from the pilot (pilot/hufs-global, round 5): the 24 models of active-models.json (백년관·어문학관·학생회관·도서관·왕산문화예술관
// detailed, the rest generic), all destructible (no independent hospital, religious or child facility: the protected list is empty),
// the pilot's baked environment (graded terrain, OSM roads / 명수당 pond / pitch, 정문, 명수당 metasequoias and grove, ridge forest,
// context) split into ground / site / planting. Local only until the user approves (registry public: false).
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, HG_PLACEMENTS, HG_BUILDING_BASE, HG_HEIGHT_GRIDS, HG_HEIGHT_RANGE_M, HG_ENV_IDS, HG_PROVENANCE } from './data.js';
import { HG_FOOTPRINTS } from './footprints.js';
import { HG_PROTECTED } from './protected.js';

const MODEL_IDS = Object.freeze(HG_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/hufsglobal/${file}`, import.meta.url).href;
const HAZE = '#c4dbea';

export const HUFS_GLOBAL = Object.freeze({
  id: 'hufsglobal',
  meta: Object.freeze({ school: '한국외국어대학교', campus: '글로벌캠퍼스', short: '외대 글로벌', modelNoun: '외대 글로벌캠퍼스' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: HG_PLACEMENTS,
  approvedCount: HG_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['centennial', 'library', 'student', 'arts', 'language', 'liberal'].filter(id => MODEL_IDS.includes(id))),
  // Start: 백년관 and the 축구장 from the pitch corner (official-01 direction): the colonnade rising to the curved end, the glass tower,
  // 도서관 · 학생회관 · 왕산문화예술관 on the slope behind. Chosen over 명수당 (reports/2026-10-29_외대글로벌_R3/frames: from the game
  // camera's height the pond reads as a forest patch). Box in world units (metres x 0.5, z = -N); azimuth = target -> camera (camera.js).
  // 390 (Astra 3rd, HFG-02): box reaches back over the pitch so the whole 백년관 (tower, stone block, both colonnade ends) sits
  // above the gesture hint (y ~492-556) and left of the weapon bag (x 314-390); checked by projecting focus points (frames/c6b).
  // 백년관 v2 (2026-10-30): the glass tower (facility-1436367110, world z ~ -14, top y ~ 14) is now a 44 m cube, so both boxes reach z -22 / -14 and y 14.
  startBuildingId: 'centennial',
  view: Object.freeze({ get startFrame() { return (globalThis.innerWidth || 1280) < 600
    ? { min: [-252, -12, -14], max: [-140, 14, 38], azimuth: -1.72, elevationDegrees: 18 }
    : { min: [-176, -4.1, -22], max: [-130, 19.9, 40], azimuth: -1.62, elevationDegrees: 12 }; } }),   // 검수반영 1차 HG1-15: 390 상자 왼쪽 16 키움(가방과 여유), 1280 상자 y +5.9(안내문이 곡면 기둥열을 안 가림)
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: HG_ENV_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: HG_HEIGHT_GRIDS, buildingBase: HG_BUILDING_BASE,
    source: 'Relative terrain estimate (Copernicus GLO-30, building-filled, canopy-lowered, graded pads / pond / pitch; pilot/hufs-global); not a survey' }),
  environment: Object.freeze({ provenance: HG_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, planting and the gate estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: HG_ENV_IDS, castShadow: Object.freeze([]), playMargin_m: 30,
      source: 'pilot/hufs-global baked environment (landscape/environment/model.gltf), split by node' }),
  }),
  // All 24 buildings break; the empty protected list is generated by the package builder.
  protected: Object.freeze({
    ...(HG_PROTECTED.length ? { manifestURL: asset('protected/manifest.json') } : {}),
    models: HG_PROTECTED,
  }),
  hazardTape: Object.freeze({ footprints: HG_FOOTPRINTS }),
  scene: Object.freeze({
    // 낮 = the preview's light (preview-hufs.js: sun (-360, 650, 260) m, sky #c4dbea), coordinates halved; 노을·해질녘 are shared presets.
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 600, far: 1350 }),
    hemisphere: Object.freeze({ sky: '#eaf5ff', ground: '#716a4c', intensity: 1.6 }),
    sun: Object.freeze({ color: '#fff1d3', intensity: 2.7, position: Object.freeze([-180, 325, 130]), shadowSpan: 300 }),
    floor: Object.freeze({ color: '#9aa58a', hidden: true, y: HG_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default HUFS_GLOBAL;
